def normalize_ozon_semantic_keyword(item, fallback_source=""):
  if isinstance(item, str):
    query = audit_str(item, 160)
    source = audit_str(fallback_source, 80)
  elif isinstance(item, dict):
    query = audit_str(item.get("query") or item.get("keyword") or item.get("text"), 160)
    source = audit_str(item.get("source") or fallback_source, 80)
  else:
    return None
  if not query:
    return None
  payload = {"query": query}
  if isinstance(item, dict):
    status = audit_str(item.get("status"), 40)
    frequency = audit_str(item.get("frequency"), 40)
    position = audit_str(item.get("position"), 40)
    ozon_count = audit_int(item.get("ozonCount") or item.get("ozon_count"), 0)
    wb_count = audit_int(item.get("wbCount") or item.get("wb_count"), 0)
    removal_reason = audit_str(item.get("removalReason") or item.get("reason"), 250)
    if status:
      payload["status"] = status
    if frequency:
      payload["frequency"] = frequency
    if position:
      payload["position"] = position
    if ozon_count > 0:
      payload["ozonCount"] = ozon_count
    if wb_count > 0:
      payload["wbCount"] = wb_count
    if removal_reason:
      payload["removalReason"] = removal_reason
    for key, limit in (("relevanceReason", 1200), ("field", 80), ("prioritySubject", 160)):
      value = audit_str(item.get(key), limit)
      if value:
        payload[key] = value
    if item.get("relevance") in ("relevant", "disputed", "irrelevant"):
      payload["relevance"] = item["relevance"]
    if item.get("manualDecision") in ("included", "excluded"):
      payload["manualDecision"] = item["manualDecision"]
    evidence = item.get("relevanceEvidence")
    if isinstance(evidence, list):
      payload["relevanceEvidence"] = [
        {"factId": value["factId"], "quote": audit_str(value.get("quote"), 500)}
        for value in evidence[:3] if isinstance(value, dict)
        and value.get("factId") in ("title", "description", "characteristics")
      ]
  if source:
    payload["source"] = source
  return payload


def normalize_ozon_semantic_keywords(items, limit=5000, fallback_source=""):
  if not isinstance(items, list):
    return []
  output = []
  seen = set()
  for item in items:
    keyword = normalize_ozon_semantic_keyword(item, fallback_source=fallback_source)
    if not keyword:
      continue
    key = audit_normalized(keyword["query"])
    if not key or key in seen:
      continue
    seen.add(key)
    output.append(keyword)
    if len(output) >= limit:
      break
  return output


def normalize_ozon_semantic_payload(payload):
  payload = payload if isinstance(payload, dict) else {}
  card_key = audit_str(payload.get("cardKey") or payload.get("card_key"), 160)
  sku = audit_str(payload.get("sku") or payload.get("id"), 120)
  offer_id = audit_str(payload.get("offerId") or payload.get("offer_id"), 120)
  title = audit_str(payload.get("title"), 240)
  seed_query = audit_str(payload.get("seedQuery") or payload.get("seed_query"), 240)
  if not card_key:
    card_key = draft_card_key(sku or offer_id or title)
  current = normalize_ozon_semantic_keywords(payload.get("current"), fallback_source="Ozon карточка")
  recommendations = normalize_ozon_semantic_keywords(payload.get("recommendations"), fallback_source="MPStats keyword-база")
  selected = normalize_ozon_semantic_keywords(payload.get("selected"), fallback_source="MPStats keyword-база")
  removal = normalize_ozon_semantic_keywords(payload.get("removal"), fallback_source="Ozon карточка")
  final_keywords = normalize_ozon_semantic_keywords(payload.get("final"), fallback_source="Ozon итог")
  meta = payload.get("meta") if isinstance(payload.get("meta"), dict) else {}
  normalized_meta = {
    "source": audit_str(meta.get("source") or "ozon-semantic-beta", 80),
    "marketplace": "Ozon",
  }
  for key, limit in (
    ("importedAt", 80),
    ("importedFrom", 180),
    ("updatedBy", 120),
  ):
    value = audit_str(meta.get(key), limit)
    if value:
      normalized_meta[key] = value
  import_history = meta.get("importHistory") if isinstance(meta.get("importHistory"), list) else []
  clean_history = []
  for item in import_history[-20:]:
    if not isinstance(item, dict):
      continue
    clean_history.append({
      "at": audit_str(item.get("at"), 80),
      "by": audit_str(item.get("by"), 120),
      "fileName": audit_str(item.get("fileName"), 180),
      "selectedAdded": audit_int(item.get("selectedAdded"), 0),
      "removalAdded": audit_int(item.get("removalAdded"), 0),
      "rejectedAdditions": audit_int(item.get("rejectedAdditions"), 0),
      "rejectedRemovals": audit_int(item.get("rejectedRemovals"), 0),
      "matchStrategy": audit_str(item.get("matchStrategy"), 120),
    })
  if clean_history:
    normalized_meta["importHistory"] = clean_history
  normalized = {
    "version": 1,
    "cardKey": card_key,
    "sku": sku,
    "offerId": offer_id,
    "title": title,
    "seedQuery": seed_query,
    "current": current,
    "recommendations": recommendations,
    "selected": selected,
    "removal": removal,
    "final": final_keywords,
    "meta": normalized_meta,
  }
  core = payload.get("semanticCore")
  if isinstance(core, dict) and core.get("relevanceVersion") == SEMANTIC_RELEVANCE_VERSION:
    core_rows = core.get("allKeywords", [])
    decisions = core.get("decisions", [])
    if not isinstance(core_rows, list) or not isinstance(decisions, list):
      raise ValueError("invalid_ozon_semantic_draft")
    if len(core_rows) > 5000 or len(decisions) > 5000:
      raise ValueError("semantic_relevance_too_many_queries")
    rows = normalize_ozon_semantic_keywords(core_rows)
    period = core.get("period") if isinstance(core.get("period"), dict) else {}
    normalized["semanticCore"] = {
      "marketplace": "Ozon", "source": "mpstats-expanding",
      "relevanceVersion": SEMANTIC_RELEVANCE_VERSION,
      "seedQuery": audit_str(core.get("seedQuery"), 240),
      "period": {key: audit_str(period.get(key), 10) for key in ("d1", "d2")},
      "allKeywords": rows, "current": current,
      "decisions": normalize_ozon_semantic_keywords(core.get("decisions")),
      "totalKeywords": len(rows),
      "relevanceCounts": {status: sum(row.get("relevance") == status for row in rows)
                          for status in ("relevant", "disputed", "irrelevant")},
    }
  final_selection = payload.get("finalSelection")
  if isinstance(final_selection, dict):
    normalized["finalSelection"] = {key: normalize_ozon_semantic_keywords(final_selection.get(key))
                                    for key in ("current", "selected", "removal")}
    period = final_selection.get("period") if isinstance(final_selection.get("period"), dict) else {}
    normalized["finalSelection"]["period"] = {key: audit_str(period.get(key), 10) for key in ("d1", "d2")}
  return normalized if card_key else None


def ozon_semantic_final_exists(payload):
  if not isinstance(payload, dict):
    return False
  final_items = payload.get("final")
  return isinstance(final_items, list) and bool(normalize_ozon_semantic_keywords(final_items, limit=1))


