def build_ozon_card_content_reoptimization_result(raw_card, semantic_payload=None, draft=None, mpstats_characteristics=None):
  raw_card = raw_card if isinstance(raw_card, dict) else {}
  raw_fields = raw_card.get("rawFields") if isinstance(raw_card.get("rawFields"), dict) else {}
  semantic_payload = normalize_ozon_semantic_payload(semantic_payload) if isinstance(semantic_payload, dict) else {}
  draft = normalize_ozon_content_payload(draft) if isinstance(draft, dict) else {}
  draft_content = draft.get("content") if isinstance(draft.get("content"), dict) else {}
  final_keywords = content_keywords_from_payload(semantic_payload.get("final"), limit=180)
  remove_keywords = content_keywords_from_payload(semantic_payload.get("removal"), limit=80)
  current_keywords = content_keywords_from_payload(semantic_payload.get("current"), limit=140)
  selected_keywords = content_keywords_from_payload(semantic_payload.get("selected"), limit=140)
  if not final_keywords:
    raise ValueError("missing_ozon_semantic_keywords")
  if not content_reoptimization_configured():
    raise ValueError("llm_key_missing")

  title = audit_str(ozon_card_value(raw_card, "title", "name"), 300)
  description = audit_str(ozon_card_value(raw_card, "description"), 6000)
  brand = audit_str(ozon_card_value(raw_card, "brand"), 180)
  category = audit_str(ozon_card_value(raw_card, "subjectName", "category", "categoryName"), 180)
  sku = audit_str(ozon_card_value(raw_card, "sku", "id", "productId"), 120)
  offer_id = audit_str(ozon_card_value(raw_card, "offerId", "offer_id", "vendorCode"), 120)
  characteristics = ozon_card_characteristics_for_content(raw_card)
  mpstats_characteristics = mpstats_characteristics if isinstance(mpstats_characteristics, list) else []
  evidence = {
    "marketplace": "Ozon",
    "card": {
      "sku": sku,
      "offerId": offer_id,
      "brand": brand,
      "category": category,
      "title": title,
      "description": description,
      "characteristics": characteristics,
      "rawSignals": {
        "price": ozon_card_value(raw_card, "price", "finalPrice", "final_price"),
        "stock": ozon_card_value(raw_card, "stock", "balance", "available_stock"),
        "rating": ozon_card_value(raw_card, "rating"),
        "feedbacks": ozon_card_value(raw_card, "feedbacks", "reviews", "comments"),
      },
    },
    "draft": {
      "title": audit_str(draft_content.get("title") or "", 300),
      "description": audit_str(draft_content.get("description") or "", 6000),
      "characteristics": draft_content.get("characteristics") if isinstance(draft_content.get("characteristics"), list) else [],
    },
    "semanticCore": {
      "finalKeywords": final_keywords,
      "currentKeywords": current_keywords,
      "selectedKeywords": selected_keywords,
      "removeKeywords": remove_keywords,
    },
    "characteristicsContext": {
      "currentCharacteristics": characteristics,
      "mpstatsCharacteristics": mpstats_characteristics[:80],
    },
    "constraints": {
      "titleMaxChars": 200,
      "descriptionMaxChars": OZON_CONTENT_REOPTIMIZE_DESCRIPTION_LIMIT,
      "descriptionTarget": "1200-2500",
      "language": "ru",
    },
  }
  messages = [
    {"role": "system", "content": OZON_CONTENT_REOPTIMIZE_SYSTEM_PROMPT},
    {"role": "user", "content": json.dumps({"evidenceBundle": evidence}, ensure_ascii=False)},
  ]
  try:
    payload, model, provider = audit_llm_chat_completion(messages)
    if not payload:
      raise ValueError("llm_key_missing")
    content = payload.get("choices", [{}])[0].get("message", {}).get("content", "")
    parsed = parse_llm_json_content(content)
    if not isinstance(parsed, dict):
      raise RuntimeError("llm_ozon_content_reoptimization_invalid_json")
  except (RuntimeError, urlerror.HTTPError, urlerror.URLError, TimeoutError, json.JSONDecodeError, KeyError, IndexError) as exc:
    raise RuntimeError(f"llm_ozon_content_reoptimization_failed:{type(exc).__name__}") from exc

  title_block = parsed.get("title") if isinstance(parsed.get("title"), dict) else {}
  description_block = parsed.get("description") if isinstance(parsed.get("description"), dict) else {}
  next_title = ozon_content_title_limit(title_block.get("value") or draft_content.get("title") or title)
  next_description = audit_str(description_block.get("value") or draft_content.get("description") or description, OZON_CONTENT_REOPTIMIZE_DESCRIPTION_LIMIT)
  next_description = content_reoptimization_remove_output_leaks(next_description, card={
    "title": title,
    "subjectName": category,
    "description": description,
    "brand": brand,
    "characteristics": [
      {"name": row.get("name"), "value": ", ".join(row.get("values") or [])}
      for row in characteristics
    ],
  }) or next_description
  next_description = content_reoptimization_apply_client_postprocess(next_description, {
    "title": title,
    "subjectName": category,
    "description": description,
    "brand": brand,
    "characteristics": [
      {"name": row.get("name"), "value": ", ".join(row.get("values") or [])}
      for row in characteristics
    ],
  })
  if not next_title or not next_description:
    raise RuntimeError("llm_ozon_content_reoptimization_empty")

  llm_characteristics = normalize_content_reoptimization_characteristics(parsed.get("characteristics"), fallback_rows=characteristics)
  fallback_characteristics = content_reoptimization_characteristic_fallback(
    {"characteristics": [
      {"name": row.get("name"), "value": ", ".join(row.get("values") or [])}
      for row in characteristics
    ]},
    final_keywords,
    available_characteristics=characteristics,
    mpstats_characteristics=mpstats_characteristics,
  )
  characteristic_draft = content_reoptimization_merge_characteristic_drafts(fallback_characteristics, llm_characteristics)
  characteristic_rows = ozon_content_characteristics_list(characteristic_draft)
  used_keywords = content_keyword_matches(f"{next_title} {next_description}", final_keywords, limit=120)
  warnings = parsed.get("_meta", {}).get("warnings", []) if isinstance(parsed.get("_meta"), dict) and isinstance(parsed.get("_meta", {}).get("warnings"), list) else []
  return {
    "draftContent": {
      "title": next_title,
      "description": next_description,
      "characteristics": characteristic_rows,
    },
    "contentOptimization": {
      "id": f"ozon-semantic-content-{int(time.time() * 1000)}",
      "createdAt": utc_now().isoformat(),
      "engine": "opticards-ozon-semantic-content-v1",
      "provider": provider,
      "model": model,
      "marketplace": "Ozon",
      "finalKeywordCount": len(final_keywords),
      "usedKeywords": used_keywords,
      "warnings": warnings[:20],
      "mpstatsCharacteristics": len(mpstats_characteristics),
    },
  }


def build_ozon_card_content_reoptimization(portal_id, payload, user):
  numeric_portal_id = ensure_ozon_portal_access(portal_id, user, edit=True, local_work=True)
  payload = payload if isinstance(payload, dict) else {}
  raw_card = payload.get("card") if isinstance(payload.get("card"), dict) else payload
  card_key = audit_str(payload.get("cardKey") or raw_card.get("cardKey"), 160)
  sku = audit_str(payload.get("sku") or ozon_card_value(raw_card, "sku", "id", "productId"), 120)
  offer_id = audit_str(payload.get("offerId") or ozon_card_value(raw_card, "offerId", "offer_id", "vendorCode"), 120)
  title = audit_str(payload.get("title") or ozon_card_value(raw_card, "title", "name"), 300)
  if not card_key:
    card_key = draft_card_key(sku or offer_id or title)
  if not card_key:
    raise ValueError("invalid_ozon_card_content_reoptimization")
  semantic_payload = normalize_ozon_semantic_payload(payload.get("semanticDraft")) if isinstance(payload.get("semanticDraft"), dict) else {}
  if not semantic_payload:
    semantic_payload = load_ozon_semantic_payload_for_card(numeric_portal_id, card_key)
  draft_payload = normalize_ozon_content_payload(payload.get("draft")) if isinstance(payload.get("draft"), dict) else {}
  if not draft_payload:
    draft_payload = load_ozon_card_draft_payload_for_card(numeric_portal_id, card_key)
  mpstats_characteristics = payload.get("mpstatsCharacteristics") if isinstance(payload.get("mpstatsCharacteristics"), list) else []
  result = build_ozon_card_content_reoptimization_result(raw_card, semantic_payload=semantic_payload, draft=draft_payload, mpstats_characteristics=mpstats_characteristics)
  previous_audit = draft_payload.get("auditResult") if isinstance(draft_payload.get("auditResult"), dict) else {}
  saved = save_ozon_card_draft(numeric_portal_id, {
    "cardKey": card_key,
    "sku": sku,
    "offerId": offer_id,
    "title": title or result["draftContent"]["title"],
    "content": result["draftContent"],
    "approval": {"contentStatus": "draft"},
    "auditStatus": "done",
    "auditResult": previous_audit,
    "source": "ozon-semantic-content",
    "contentOptimization": result["contentOptimization"],
  }, user)
  result["draft"] = saved.get("draft")
  return result


def build_ozon_card_audit(portal_id, payload, user):
  numeric_portal_id = ensure_ozon_portal_access(portal_id, user, edit=True, local_work=True)
  payload = payload if isinstance(payload, dict) else {}
  raw_card = payload.get("card") if isinstance(payload.get("card"), dict) else payload
  card_key = audit_str(payload.get("cardKey") or raw_card.get("cardKey"), 160)
  sku = audit_str(payload.get("sku") or ozon_card_value(raw_card, "sku", "id", "productId"), 120)
  offer_id = audit_str(payload.get("offerId") or ozon_card_value(raw_card, "offerId", "offer_id", "vendorCode"), 120)
  title = audit_str(payload.get("title") or ozon_card_value(raw_card, "title", "name"), 300)
  if not card_key:
    card_key = draft_card_key(sku or offer_id or title)
  if not card_key:
    raise ValueError("invalid_ozon_card_audit")
  description = audit_str(ozon_card_value(raw_card, "description"), 6000)
  category = audit_str(ozon_card_value(raw_card, "subjectName", "category", "categoryName"), 180)
  brand = audit_str(ozon_card_value(raw_card, "brand"), 180)
  photos = ozon_card_value(raw_card, "photos")
  characteristics = ozon_card_value(raw_card, "characteristics")
  price = ozon_card_value(raw_card, "price", "finalPrice", "final_price")
  stock = ozon_card_value(raw_card, "stock", "balance", "available_stock")
  warnings = []
  if not title:
    warnings.append("нет названия")
  if not sku:
    warnings.append("нет SKU")
  if not description:
    warnings.append("нет описания")
  if not brand:
    warnings.append("бренд не указан")
  if not category:
    warnings.append("категория не указана")
  if not isinstance(photos, list) or not photos:
    warnings.append("нет фото")
  if not ((isinstance(characteristics, list) and characteristics) or (isinstance(characteristics, dict) and characteristics)):
    warnings.append("нет характеристик")
  if price in (None, "", [], {}):
    warnings.append("нет цены")
  if stock in (None, "", [], {}):
    warnings.append("нет остатка")
  recommended_title = title or " ".join([brand, category, sku]).strip()
  recommended_description = description or " ".join([recommended_title, category, brand]).strip()
  audit_result = {
    "marketplace": "Ozon",
    "engine": "opticards-ozon-snapshot-audit-v1",
    "createdAt": utc_now().isoformat(),
    "summary": {
      "status": "attention" if warnings else "ok",
      "warnings": warnings[:20],
      "filledBlocks": sum(1 for value in (title, sku, description, brand, category, photos, characteristics, price, stock) if value not in (None, "", [], {})),
      "totalBlocks": 9,
    },
    "recommendations": {
      "title": recommended_title,
      "description": recommended_description,
    },
  }
  return save_ozon_card_draft(numeric_portal_id, {
    "cardKey": card_key,
    "sku": sku,
    "offerId": offer_id,
    "title": title or recommended_title,
    "content": {
      "title": recommended_title,
      "description": recommended_description,
      "characteristics": characteristics if isinstance(characteristics, (list, dict)) else [],
    },
    "approval": {"contentStatus": "draft"},
    "auditStatus": "done",
    "auditResult": audit_result,
    "source": "ozon-audit",
  }, user)


_AUTOMATIC_SEO_SERVICES = {}
_AUTOMATIC_SEO_SERVICE_LOCK = threading.Lock()
_BITRIX_SEO_NOTIFIERS = {}


def automatic_seo_service():
  from automatic_seo import AutomaticSeoService
  from automatic_seo_host import MarketplaceSeoHost
  root = DB_PATH.parent / "automatic-seo"
  with _AUTOMATIC_SEO_SERVICE_LOCK:
    key = str(root.resolve())
    if key not in _AUTOMATIC_SEO_SERVICES:
      _AUTOMATIC_SEO_SERVICES[key] = AutomaticSeoService(MarketplaceSeoHost(sys.modules[__name__]), root)
    return _AUTOMATIC_SEO_SERVICES[key]


def bitrix_seo_notifier():
  from automatic_seo_host import BitrixSeoNotifications
  service = automatic_seo_service()
  key = str(service.root.resolve())
  with _AUTOMATIC_SEO_SERVICE_LOCK:
    if key not in _BITRIX_SEO_NOTIFIERS:
      _BITRIX_SEO_NOTIFIERS[key] = BitrixSeoNotifications(sys.modules[__name__], service)
    return _BITRIX_SEO_NOTIFIERS[key]


def automatic_seo_completed(portal, batch, version):
  intent_id = version.get('_resumeIntentId')
  if intent_id:
    with connect_db() as db:
      row = db.execute('SELECT details_json FROM admin_events WHERE id=? AND action=?', (intent_id,'seo_resume_requested')).fetchone()
      if row:
        details = json.loads(row['details_json'] or '{}')
        details.update(phase='finished',status=version['status'],finishedAt=utc_now().isoformat())
        db.execute('UPDATE admin_events SET details_json=? WHERE id=?',(json.dumps(details),intent_id))
  bitrix_seo_notifier().enqueue(portal, batch, version)


def recover_automatic_seo_handoffs():
  """Only owner-authorized, scoped intents; restore run locks before accepting HTTP."""
  with connect_db() as db:
    rows = db.execute("SELECT * FROM admin_events WHERE action='seo_resume_requested' ORDER BY id").fetchall()
  for row in rows:
    details = {}
    try:
      details = json.loads(row["details_json"] or "{}")
      if details.get("phase") in {"finished", "failed"}:
        continue
      with connect_db() as db:
        user = db.execute("SELECT * FROM users WHERE login=? AND is_active=1", (row["actor_login"],)).fetchone()
      if not user or not user_is_admin(user):
        raise PermissionError("forbidden")
      if int(details.get("attempts", 0)) >= 3:
        raise ValueError("seo_resume_attempt_limit")
      details.update(phase="resuming", attempts=int(details.get("attempts", 0))+1)
      with connect_db() as db:
        db.execute("UPDATE admin_events SET details_json=? WHERE id=?", (json.dumps(details),row["id"]))
      portal, batch = int(row["portal_id"]), str(details["batchId"])
      service = automatic_seo_service()
      result = service.resume(portal,batch,dict(user),int(details["version"]),str(details["taskHash"]),row["id"])
      details.update(phase="running", resumedAt=utc_now().isoformat(), preservedCount=result['versions'][-1].get('continuation',{}).get('preservedCount',0))
    except Exception as exc:
      details = details if 'details' in locals() and isinstance(details, dict) else {}
      details.update(phase="failed", errorCode=str(exc) if isinstance(exc, (ValueError, PermissionError)) else "seo_resume_failed")
    with connect_db() as db:
      current = db.execute('SELECT details_json FROM admin_events WHERE id=?',(row['id'],)).fetchone()
      if current and json.loads(current['details_json']).get('phase') == 'finished':
        continue
      db.execute("UPDATE admin_events SET details_json=? WHERE id=?", (json.dumps(details),row["id"]))


def automatic_seo_handoff_report(portal, batch, user):
  if not user_is_admin(user):
    raise PermissionError("forbidden")
  service = automatic_seo_service()
  service.context(portal,batch,user,edit=True)
  directory = service.directory(portal,batch)
  with service.lock(directory):
    state = service.load(directory)
    version = state['versions'][-1]
  from automatic_seo import fingerprint
  paths = sorted((directory/'checkpoints').glob('handoff-*/manifest.json'))
  latest_checkpoint = json.loads(paths[-1].read_text()) if paths else None
  preservation = version.get('_preservation')
  if preservation:
    manifest = {'preservedResults': preservation['resultHashes'], 'savedAt': preservation['savedAt']}
  else:
    if not latest_checkpoint:
      raise ValueError("seo_checkpoint_missing")
    manifest = latest_checkpoint
  preserved = manifest['preservedResults']
  unchanged = [sku for sku,digest in preserved.items() if sku in version['results'] and fingerprint(version['results'][sku])==digest]
  checkpoint_report = {}
  repair_baseline = version.get('_repairBaseline')
  if repair_baseline:
    baseline_version = next((v for v in state['versions'] if v['number'] == repair_baseline['number']), None)
    hashes = repair_baseline['resultHashes']
    unchanged_baseline = sum(baseline_version is not None and sku in baseline_version['results']
        and fingerprint(baseline_version['results'][sku]) == digest for sku, digest in hashes.items())
    checkpoint_report['repair'] = {'fromVersion': repair_baseline['number'], 'baselineResults': len(hashes),
        'unchangedBaselineResults': unchanged_baseline, 'baselineVersionUnchanged': unchanged_baseline == len(hashes)}
  if latest_checkpoint and latest_checkpoint.get('version') == version['number']:
    checkpoint_hashes = latest_checkpoint['preservedResults']
    unchanged_checkpoint = sum(sku in version['results'] and fingerprint(version['results'][sku]) == digest
                               for sku, digest in checkpoint_hashes.items())
    checkpoint_report['latestHandoff'] = {'preservedCount':len(checkpoint_hashes),
        'unchangedCount':unchanged_checkpoint,'allPreserved':unchanged_checkpoint==len(checkpoint_hashes),
        'doneAtCheckpoint':latest_checkpoint['done'],'savedAt':latest_checkpoint['savedAt']}
  return {"version":version['number'],"status":version['status'],"done":version['done'],"total":version['total'],
          "completedCount":len(version['results']),"workers":version.get('workers',1),"maxConcurrentRequests":LLM_CONCURRENT_REQUESTS,
          "preservedSkus":list(preserved),"unchangedCount":len(unchanged),"allPreserved":len(unchanged)==len(preserved),
          "checkpointAt":manifest['savedAt'],"activeCards":version.get('activeCards',{}),
          "preservationKind":"previous-version" if preservation else "handoff-checkpoint",
          "preservedFromVersion":preservation['fromVersion'] if preservation else version['number'],
          **({"sourcePreserved":version.get('sourceCapturedAt')==preservation['sourceCapturedAt']
                                  and fingerprint(version.get('cards'))==preservation['cardsHash']} if preservation else {}),
          **checkpoint_report,
          "errors":[{"sku":e['sku'],"code":e['code']} for e in version.get('errors',[])]}


def list_ozon_tasks(portal_id, user):
  numeric_portal_id = ensure_ozon_portal_access(portal_id, user, edit=False)
  with connect_db() as db:
    task_rows = db.execute(
      """
      SELECT *
      FROM ozon_tasks
      WHERE portal_id = ?
      ORDER BY created_at ASC, id ASC
      """,
      (numeric_portal_id,),
    ).fetchall()
    semantic_rows = db.execute(
      """
      SELECT card_key, payload_json
      FROM ozon_semantic_drafts
      WHERE portal_id = ?
      """,
      (numeric_portal_id,),
    ).fetchall()
    content_rows = db.execute(
      """
      SELECT card_key, payload_json, audit_status
      FROM ozon_card_drafts
      WHERE portal_id = ?
      """,
      (numeric_portal_id,),
    ).fetchall()
    event_rows = db.execute(
      """
      SELECT *
      FROM ozon_task_events
      WHERE portal_id = ?
      ORDER BY event_at DESC, id DESC
      LIMIT 30
      """,
      (numeric_portal_id,),
    ).fetchall()
  semantic_map = {}
  for row in semantic_rows:
    try:
      payload = normalize_ozon_semantic_payload(json.loads(row["payload_json"] or "{}")) or {}
    except (TypeError, json.JSONDecodeError):
      payload = {}
    semantic_map[row["card_key"]] = {"hasFinal": ozon_semantic_final_exists(payload)}
  content_map = {}
  for row in content_rows:
    try:
      payload = normalize_ozon_content_payload(json.loads(row["payload_json"] or "{}")) or {}
    except (TypeError, json.JSONDecodeError):
      payload = {}
    content_map[row["card_key"]] = {
      "hasFinalContent": ozon_content_final_exists(payload),
      "auditStatus": row["audit_status"] or payload.get("auditStatus") or "idle",
    }
  return {
    "portalId": str(numeric_portal_id),
    "tasks": [public_ozon_task(row, semantic_map=semantic_map, content_map=content_map) for row in task_rows],
    "recentEvents": [public_ozon_task_event(row) for row in event_rows],
  }


def save_ozon_tasks(portal_id, payload, user):
  numeric_portal_id = ensure_ozon_portal_access(portal_id, user, edit=True)
  payload = payload if isinstance(payload, dict) else {}
  raw_tasks = payload.get("tasks") if isinstance(payload.get("tasks"), list) else []
  with connect_db() as db:
    automatic_ids = {row["task_id"] for row in db.execute("SELECT task_id, payload_json FROM ozon_tasks WHERE portal_id = ?", (numeric_portal_id,)).fetchall()
                     if json.loads(row["payload_json"] or "{}").get("optimizationMode") == "automatic"}
  tasks = []
  seen = set()
  for raw_task in raw_tasks:
    task = normalize_ozon_task(raw_task)
    if task and task["id"] in automatic_ids:
      task["optimizationMode"] = "automatic"
    identity = (task["cardKey"], task.get("optimizationMode", "")) if task else None
    if not task or identity in seen:
      continue
    seen.add(identity)
    tasks.append(task)
  if len(tasks) > 500 and any(task.get("optimizationMode") == "automatic" for task in tasks):
    raise ValueError("ozon_task_limit")
  tasks = tasks[:500]
  now = utc_now().isoformat()
  actor_login = user_login_value(user) or ""
  with connect_db() as db:
    previous_rows = db.execute(
      "SELECT task_id, card_key, status, title, payload_json FROM ozon_tasks WHERE portal_id = ?",
      (numeric_portal_id,),
    ).fetchall()
    previous = {row["task_id"]: row for row in previous_rows}
    next_task_ids = {task["id"] for task in tasks}
    for task in tasks:
      previous_row = previous.get(task["id"])
      previous_payload = json.loads(previous_row["payload_json"] or "{}") if previous_row else {}
      if previous_payload.get("optimizationMode") == "automatic":
        # Report transitions are version-checked by the report API, never by
        # the generic task-list save or a stale browser's copy of that list.
        task["optimizationMode"] = "automatic"
        task["workType"], task["workTypes"] = "content", ["content"]
        task["status"] = previous_row["status"]
        for key in ("batchId", "cardKey", "sku", "offerId", "batchPosition"):
          task[key] = previous_payload.get(key, task.get(key))
      elif task.get("optimizationMode") == "automatic":
        if db.execute("SELECT 1 FROM ozon_task_events WHERE portal_id = ? AND task_id = ? AND action = 'deleted' LIMIT 1", (numeric_portal_id, task["id"])).fetchone():
          raise ValueError("seo_deleted_task_restore_blocked")
        task["status"] = "draft"
      db.execute(
        """
        INSERT INTO ozon_tasks (
          portal_id, task_id, card_key, sku, offer_id, title, category,
          status, work_type, payload_json, created_by, updated_by, updated_at
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(portal_id, task_id) DO UPDATE SET
          card_key = excluded.card_key,
          sku = excluded.sku,
          offer_id = excluded.offer_id,
          title = excluded.title,
          category = excluded.category,
          status = excluded.status,
          work_type = excluded.work_type,
          payload_json = excluded.payload_json,
          updated_by = excluded.updated_by,
          updated_at = CURRENT_TIMESTAMP
        """,
        (
          numeric_portal_id,
          task["id"],
          task["cardKey"],
          task["sku"],
          task["offerId"],
          task["title"],
          task["category"],
          task["status"],
          task["workType"],
          json.dumps(task, ensure_ascii=False, separators=(",", ":")),
          actor_login or None,
          actor_login or None,
        ),
      )
      if not previous_row:
        action = "created"
        label = f"Создана Ozon-задача: {task['title']}"
      elif previous_row["status"] != task["status"]:
        action = task["status"]
        label = f"{task['title']}: {OZON_TASK_STATUS_LABELS.get(task['status'], task['status'])}"
      else:
        action = ""
        label = ""
      if action:
        db.execute(
          """
          INSERT INTO ozon_task_events (portal_id, task_id, card_key, action, label, actor_login, event_at)
          VALUES (?, ?, ?, ?, ?, ?, ?)
          """,
          (numeric_portal_id, task["id"], task["cardKey"], action, label[:500], actor_login, now),
        )
    for row in previous_rows:
      if row["task_id"] not in next_task_ids:
        db.execute(
          """
          INSERT INTO ozon_task_events (portal_id, task_id, card_key, action, label, actor_login, event_at)
          VALUES (?, ?, ?, 'deleted', ?, ?, ?)
          """,
          (numeric_portal_id, row["task_id"], row["card_key"], f"Удалена Ozon-задача: {row['title']}"[:500], actor_login, now),
        )
    db.execute(
      """
      DELETE FROM ozon_tasks
      WHERE portal_id = ?
        AND task_id NOT IN ({})
      """.format(",".join("?" for _ in next_task_ids) or "''"),
      [numeric_portal_id, *next_task_ids],
    )
    linked_periods = []
    link_batch = str(payload.get("linkBatchId") or "")
    if payload.get("workPeriodLinks"):
      batch_tasks = [t for t in tasks if t.get("batchId") == link_batch]
      if not link_batch or not batch_tasks:
        raise ValueError("invalid_work_period_link")
      types = list(dict.fromkeys(kind for t in batch_tasks for kind in (t.get("workTypes") or ["content"])))
      linked_periods = link_batch_to_work_periods_in_db(db, numeric_portal_id, link_batch, types,
          payload["workPeriodLinks"], user, batch_tasks[0].get("batchTitle", ""))
    removed_batches = {json.loads(r["payload_json"] or "{}").get("batchId") for r in previous_rows if r["task_id"] not in next_task_ids}
    remaining_batches = {t.get("batchId") for t in tasks}
    for removed_batch in removed_batches - remaining_batches - {None, ""}:
      unlink_work_period_task_links_in_db(db, numeric_portal_id,
          linked_task_ids=work_period_task_link_ids(removed_batch, ["semantic", "content", "prices", "stocks"]),
          linked_batch_ids=[removed_batch], user=user)
    for batch in remaining_batches - {None, ""}:
      sync_work_period_task_statuses_for_batch_in_db(db, numeric_portal_id, batch, user)
  record_admin_event(user, "ozon_tasks_updated", "portal", numeric_portal_id, portal_id=numeric_portal_id, details={
    "taskCount": len(tasks),
  })
  return {**list_ozon_tasks(numeric_portal_id, user), "workPeriods": linked_periods}


def link_batch_to_work_periods_in_db(db, portal_id, batch_id, work_types, targets, user, title=""):
  """Link within the task's transaction: a bad/cross-cabinet target rolls back creation."""
  if not isinstance(targets, list) or len(targets) > 100:
    raise ValueError("invalid_work_period_link")
  output, seen = [], set()
  for target in targets:
    if not isinstance(target, dict):
      raise ValueError("invalid_work_period_link")
    try:
      period_id = int(target.get("periodId") or 0)
    except (ValueError, TypeError):
      raise ValueError("invalid_work_period_link") from None
    task_key = clean_work_period_task_key(target.get("taskKey"))
    if (period_id, task_key) in seen:
      continue
    seen.add((period_id, task_key))
    row = db.execute('SELECT * FROM portal_work_periods WHERE portal_id=? AND id=? AND status != ?',
                     (portal_id, period_id, 'archived')).fetchone()
    if not row:
      raise ValueError("work_period_not_found")
    if row['workflow_version']==2: raise ValueError('workflow_versioned_plan_required')
    plan = normalize_work_period_tasks(parse_work_period_json(row["tasks_json"], []))
    item = next((t for t in plan if t["key"] == task_key), None)
    if not item:
      raise ValueError("work_period_task_not_found")
    if item["status"] == "excluded":
      raise ValueError("work_period_task_excluded")
    at = utc_now().isoformat()
    ids = work_period_task_link_ids(batch_id, work_types)
    item.update(linkedTaskIds=clean_work_period_links([*item.get("linkedTaskIds", []), *ids]),
                linkedBatchIds=clean_work_period_links([*item.get("linkedBatchIds", []), batch_id]),
                status="in_progress" if item["status"] == "planned" else item["status"],
                statusUpdatedAt=at, statusUpdatedBy=user_login_value(user))
    item["history"] = clean_work_period_history([*item.get("history", []),
        {"action": "linked_task", "at": at, "by": user_login_value(user), "comment": title, "reason": ", ".join(ids)}])
    db.execute("UPDATE portal_work_periods SET tasks_json=?, report_json='{}', status=?, updated_by=?, updated_at=CURRENT_TIMESTAMP WHERE portal_id=? AND id=?",
        (json.dumps(plan, ensure_ascii=False), "active" if row["status"] == "reported" else row["status"], user_login_value(user), portal_id, period_id))
    output.append(public_portal_work_period(db.execute('SELECT * FROM portal_work_periods WHERE portal_id=? AND id=?', (portal_id, period_id)).fetchone()))
  return output


def workset_batch_draft_payload(card, user, batch_id, existing_payload=None, batch_options=None):
  batch_options = batch_options if isinstance(batch_options, dict) else {}
  work_types = normalize_work_types(batch_options.get("workTypes"))
  comment = str(batch_options.get("comment") or "").strip()[:700]
  title = str(batch_options.get("title") or "").strip()[:180]
  assignee_login = str(batch_options.get("assigneeLogin") or "").strip()[:120]
  created_at = batch_options.get("createdAt") or utc_now().isoformat()
  cards_count = int(batch_options.get("cardsCount") or 0)
  position = int(batch_options.get("position") or 0)
  if not title:
    title = work_package_title(work_types, cards_count, comment)
  payload = normalize_card_draft_payload(existing_payload or {})
  meta = payload.get("meta") if isinstance(payload.get("meta"), dict) else {}
  approval = meta.get("approval") if isinstance(meta.get("approval"), dict) else {}
  if str(approval.get("status") or "draft") == "draft":
    approval = {
      **approval,
      "status": "draft",
      "submittedBy": approval.get("submittedBy") or "",
      "assigneeLogin": approval.get("assigneeLogin") or assignee_login,
    }
  approval_sections = meta.get("approvalSections") if isinstance(meta.get("approvalSections"), dict) else {}
  next_approval_sections = {**approval_sections}
  for work_type in work_types:
    if work_type not in APPROVAL_SECTION_LABELS:
      continue
    section = next_approval_sections.get(work_type) if isinstance(next_approval_sections.get(work_type), dict) else {}
    if str(section.get("status") or "draft") == "draft":
      next_approval_sections[work_type] = {
        **section,
        "status": "draft",
        "submittedBy": section.get("submittedBy") or "",
        "assigneeLogin": section.get("assigneeLogin") or assignee_login,
      }
  payload["meta"] = {
    **meta,
    "approval": approval,
    "approvalSections": next_approval_sections,
    "card": {
      "nmID": card["nmID"],
      "vendorCode": card["vendorCode"],
      "title": card["title"],
      "subjectName": card["subjectName"],
    },
    "batch": {
      "id": batch_id,
      "kind": "mass_work_package",
      "createdBy": user["login"],
      "createdAt": created_at,
      "title": title,
      "assigneeLogin": assignee_login,
      "cardsCount": cards_count,
      "position": position,
      "workTypes": work_types,
      "workTypeLabels": work_type_labels(work_types),
      "comment": comment,
    },
  }
  return payload


def wb_automatic_task_scope(portal_id, user):
  if not user_can_access_portal(user, portal_id):
    raise PermissionError('forbidden')
  row = get_portal_row(portal_id, user, scope_only=True)
  if not row or not row['is_active']:
    raise ValueError('portal_not_found')
  if audit_normalized(row['marketplace']) not in {'wildberries', 'wb'}:
    raise ValueError('wb_portal_required')
  return int(row['id'])


def list_wb_automatic_tasks(portal_id, user):
  portal = wb_automatic_task_scope(portal_id, user)
  with connect_db() as db:
    rows = db.execute('SELECT * FROM automatic_seo_tasks WHERE portal_id=? ORDER BY id', (portal,)).fetchall()
  return {'portalId': str(portal), 'tasks': [dict(json.loads(r['payload_json']), status=r['status'],
          updatedAt=r['updated_at'], updatedBy=r['updated_by']) for r in rows]}


def create_wb_automatic_tasks(portal_id, raw_cards, user, options):
  portal = wb_automatic_task_scope(portal_id, user)
  team = portal_team_roles(portal)
  if not (user_can_manage_portals(user) or team.get('tech') == user_login_value(user)):
    raise PermissionError('forbidden')
  if not isinstance(raw_cards, list) or not 1 <= len(raw_cards) <= 200:
    raise ValueError('seo_invalid_task_scope')
  cards = [normalize_workset_card(c) for c in raw_cards]
  if len({c['nmID'] for c in cards}) != len(cards) or not all(re.fullmatch(r'[1-9]\d{2,19}', c['nmID']) for c in cards):
    raise ValueError('seo_invalid_task_scope')
  batch = 'wb-auto-' + secrets.token_hex(12)
  title = clean_report_text(options.get('title') or f'Автоматическая оптимизация WB: {len(cards)} карточек', 180)
  links = options.get('workPeriodLinks') or []
  if not links and (options.get('workPeriodId') or options.get('periodId')):
    links = [{'periodId': options.get('workPeriodId') or options.get('periodId'),
              'taskKey': options.get('workPeriodTaskKey') or options.get('taskKey')}]
  with connect_db() as db:
    db.execute('BEGIN IMMEDIATE')
    existing = db.execute('SELECT sku FROM automatic_seo_tasks WHERE portal_id=? AND status NOT IN (?,?,?)',
                          (portal, 'approved', 'done', 'skipped')).fetchall()
    if len(existing) + len(cards) > 500:
      raise ValueError('seo_task_limit')
    if {r['sku'] for r in existing} & {c['nmID'] for c in cards}:
      raise ValueError('seo_task_already_exists')
    for position, card in enumerate(cards):
      task = {'id': batch + '-' + str(position), 'cardKey': card['cardKey'], 'sku': card['nmID'],
        'offerId': card['vendorCode'], 'title': card['title'], 'category': card['subjectName'], 'status': 'draft',
        'workType': 'content', 'workTypes': ['content'], 'optimizationMode': 'automatic', 'batchId': batch,
        'batchTitle': title, 'batchPosition': position, 'batchCreatedAt': utc_now().isoformat(),
        'workComment': clean_work_period_note(options.get('comment'), 700)}
      db.execute('INSERT INTO automatic_seo_tasks (portal_id,batch_id,task_id,card_key,sku,payload_json,created_by,updated_by) VALUES (?,?,?,?,?,?,?,?)',
                 (portal, batch, task['id'], task['cardKey'], task['sku'], json.dumps(task, ensure_ascii=False), user['login'], user['login']))
    periods = link_batch_to_work_periods_in_db(db, portal, batch, ['content'], links, user, title)
  record_admin_event(user, 'automatic_seo_task_created', 'portal', portal, portal_id=portal,
                     details={'batchId': batch, 'cardCount': len(cards), 'marketplace': 'Wildberries'})
  return {'portalId': str(portal), 'batchId': batch, 'tasksCreated': len(cards), 'tasksUpdated': 0,
          'workTypes': ['content'], 'workset': {'cards': cards}, 'automaticTasks': list_wb_automatic_tasks(portal, user)['tasks'],
          'workPeriods': periods, 'workflow': approval_workflow(portal, user)}


def delete_wb_automatic_batch(portal_id, batch, user):
  portal = wb_automatic_task_scope(portal_id, user)
  team = portal_team_roles(portal)
  if not (user_can_manage_portals(user) or team.get('tech') == user_login_value(user)):
    raise PermissionError('forbidden')
  with connect_db() as db:
    db.execute('DELETE FROM automatic_seo_tasks WHERE portal_id=? AND batch_id=?', (portal, batch))
    unlink_work_period_task_links_in_db(db, portal, linked_task_ids=work_period_task_link_ids(batch, ['content']), linked_batch_ids=[batch], user=user)
  return list_wb_automatic_tasks(portal, user)


def create_workset_tasks(portal_id, raw_cards, user, options=None):
  if isinstance(options, dict) and options.get("optimizationMode") == "automatic":
    return create_wb_automatic_tasks(portal_id, raw_cards, user, options)
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  options = options if isinstance(options, dict) else {}
  work_types = normalize_work_types(options.get("workTypes"))
  comment = str(options.get("comment") or "").strip()[:700]
  title = str(options.get("title") or "").strip()[:180]
  link_targets = []
  seen_link_targets = set()
  raw_links = options.get("workPeriodLinks") if isinstance(options.get("workPeriodLinks"), list) else []
  for item in raw_links:
    if isinstance(item, dict):
      raw_period_id = item.get("periodId") or item.get("period_id")
      raw_task_key = item.get("taskKey") or item.get("task_key")
    elif isinstance(item, str) and ":" in item:
      raw_period_id, raw_task_key = item.split(":", 1)
    else:
      raw_period_id = ""
      raw_task_key = ""
    link_period_id, link_task_key = ensure_work_period_link_target(numeric_portal_id, raw_period_id, raw_task_key)
    target_key = f"{link_period_id}:{link_task_key}"
    if link_period_id and link_task_key and target_key not in seen_link_targets:
      seen_link_targets.add(target_key)
      link_targets.append((link_period_id, link_task_key))
  if not link_targets:
    link_period_id, link_task_key = ensure_work_period_link_target(
      numeric_portal_id,
      options.get("workPeriodId") or options.get("periodId"),
      options.get("workPeriodTaskKey") or options.get("taskKey"),
    )
    if link_period_id and link_task_key:
      link_targets.append((link_period_id, link_task_key))
  team = portal_team_roles(numeric_portal_id)
  assignee_login = str(options.get("assigneeLogin") or team.get("tech") or "").strip()[:120]
  workset = save_portal_workset(numeric_portal_id, raw_cards, user)
  cards = workset["cards"]
  batch_id = f"batch-{int(time.time())}-{secrets.token_hex(4)}"
  batch_created_at = utc_now().isoformat()
  batch_options = {
    "workTypes": work_types,
    "comment": comment,
    "title": title,
    "assigneeLogin": assignee_login,
    "createdAt": batch_created_at,
    "cardsCount": len(cards),
  }
  created = 0
  kept = 0
  init_db()
  with connect_db() as db:
    for position, card in enumerate(cards):
      previous = db.execute(
        "SELECT payload_json FROM card_drafts WHERE portal_id = ? AND card_key = ?",
        (numeric_portal_id, card["cardKey"]),
      ).fetchone()
      previous_payload = None
      if previous:
        try:
          previous_payload = json.loads(previous["payload_json"])
        except (TypeError, json.JSONDecodeError):
          previous_payload = None
      payload = workset_batch_draft_payload(card, user, batch_id, previous_payload, {
        **batch_options,
        "position": position,
      })
      payload_json = json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
      cursor = db.execute(
        """
        INSERT INTO card_drafts (
          portal_id, card_key, nm_id, vendor_code, payload_json,
          audit_status, created_by, updated_by
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(portal_id, card_key) DO UPDATE SET
          nm_id = COALESCE(NULLIF(excluded.nm_id, ''), nm_id),
          vendor_code = COALESCE(NULLIF(excluded.vendor_code, ''), vendor_code),
          payload_json = excluded.payload_json,
          audit_status = excluded.audit_status,
          updated_by = excluded.updated_by,
          updated_at = CURRENT_TIMESTAMP
        """,
        (
          numeric_portal_id,
          card["cardKey"],
          card["nmID"],
          card["vendorCode"],
          payload_json,
          payload["auditStatus"],
          user["login"],
          user["login"],
        ),
      )
      if previous:
        kept += 1
      else:
        created += 1
  linked_periods = []
  for link_period_id, link_task_key in link_targets:
    linked_periods.append(update_portal_work_period(numeric_portal_id, {
      "periodId": link_period_id,
      "action": "link_task",
      "taskKey": link_task_key,
      "linkedTaskIds": work_period_task_link_ids(batch_id, work_types),
      "linkedBatchIds": [batch_id],
      "allowMultiple": True,
      "comment": title or comment or work_package_title(work_types, len(cards), comment),
    }, user))
  result = {
    "portalId": str(numeric_portal_id),
    "batchId": batch_id,
    "workTypes": work_types,
    "workTypeLabels": work_type_labels(work_types),
    "comment": comment,
    "assigneeLogin": assignee_login,
    "cardsCount": len(cards),
    "tasksCreated": created,
    "tasksUpdated": kept,
    "workset": list_portal_workset(numeric_portal_id, user),
    "workflow": approval_workflow(numeric_portal_id, user),
  }
  if linked_periods:
    result["workPeriod"] = linked_periods[0]
    result["workPeriods"] = linked_periods
  return result


def delete_card_work_tasks(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  batch_id = str(payload.get("batchId") or payload.get("batch_id") or "").strip()[:120]
  raw_work_types = payload.get("workTypes")
  if raw_work_types is None:
    raw_work_types = [payload.get("workType") or payload.get("work_type")]
  work_types = normalize_optional_work_types(raw_work_types)
  raw_card_keys = payload.get("cardKeys") if isinstance(payload.get("cardKeys"), list) else []
  if payload.get("cardKey"):
    raw_card_keys.append(payload.get("cardKey"))
  card_keys = []
  seen_card_keys = set()
  for raw_key in raw_card_keys:
    card_key = draft_card_key(raw_key)
    if card_key and card_key not in seen_card_keys:
      seen_card_keys.add(card_key)
      card_keys.append(card_key)
  if not batch_id and not card_keys:
    raise ValueError("invalid_task_delete")

  init_db()
  updated = 0
  matched = 0
  removed_types = set()
  updated_work_periods = []
  now = utc_now().isoformat()
  with connect_db() as db:
    if batch_id:
      rows = db.execute(
        """
        SELECT id, card_key, payload_json
        FROM card_drafts
        WHERE portal_id = ?
          AND json_extract(payload_json, '$.meta.batch.id') = ?
        """,
        (numeric_portal_id, batch_id),
      ).fetchall()
    else:
      placeholders = ",".join("?" for _ in card_keys)
      rows = db.execute(
        f"""
        SELECT id, card_key, payload_json
        FROM card_drafts
        WHERE portal_id = ? AND card_key IN ({placeholders})
        """,
        [numeric_portal_id, *card_keys],
      ).fetchall()

    for row in rows:
      try:
        draft_payload = json.loads(row["payload_json"])
      except (TypeError, json.JSONDecodeError):
        continue
      draft_payload = normalize_card_draft_payload(draft_payload)
      meta = draft_payload.get("meta") if isinstance(draft_payload.get("meta"), dict) else {}
      batch = meta.get("batch") if isinstance(meta.get("batch"), dict) else {}
      current_work_types = normalize_optional_work_types(batch.get("workTypes"))
      if not current_work_types:
        continue
      target_work_types = work_types or current_work_types
      target_set = set(target_work_types)
      row_removed_types = [work_type for work_type in current_work_types if work_type in target_set]
      if not row_removed_types:
        continue
      matched += 1
      removed_types.update(row_removed_types)
      remaining_work_types = [work_type for work_type in current_work_types if work_type not in target_set]
      approval_sections = meta.get("approvalSections") if isinstance(meta.get("approvalSections"), dict) else {}
      approval_sections = {
        key: value
        for key, value in approval_sections.items()
        if key not in row_removed_types
      }
      if approval_sections:
        meta["approvalSections"] = approval_sections
      else:
        meta.pop("approvalSections", None)

      removal_history = meta.get("taskRemovalHistory") if isinstance(meta.get("taskRemovalHistory"), list) else []
      removal_history.append({
        "at": now,
        "by": user["login"],
        "batchId": batch.get("id") or "",
        "cardKey": row["card_key"],
        "workTypes": row_removed_types,
      })
      meta["taskRemovalHistory"] = removal_history[-50:]

      if remaining_work_types:
        previous_title = str(batch.get("title") or "")
        previous_auto_title = work_package_title(current_work_types, batch.get("cardsCount"), batch.get("comment"))
        batch = {
          **batch,
          "workTypes": remaining_work_types,
          "workTypeLabels": [WORK_TYPE_LABELS.get(item, item) for item in remaining_work_types],
        }
        if not previous_title or previous_title == previous_auto_title:
          batch["title"] = work_package_title(remaining_work_types, batch.get("cardsCount"), batch.get("comment"))
        meta["batch"] = batch
      else:
        meta.pop("batch", None)

      draft_payload["meta"] = meta
      db.execute(
        """
        UPDATE card_drafts
        SET payload_json = ?, audit_status = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND portal_id = ?
        """,
        (
          json.dumps(draft_payload, ensure_ascii=False, separators=(",", ":")),
          draft_payload.get("auditStatus") or "idle",
          user["login"],
          row["id"],
          numeric_portal_id,
        ),
      )
      updated += 1

    if batch_id and removed_types:
      updated_work_periods = unlink_work_period_task_links_in_db(
        db,
        numeric_portal_id,
        linked_task_ids=work_period_task_link_ids(batch_id, sorted(removed_types)),
        linked_batch_ids=[batch_id],
        user=user,
        comment="задача удалена из кабинета",
      )

  record_admin_event(user, "card_work_tasks_deleted", "portal", numeric_portal_id, portal_id=numeric_portal_id, details={
    "batchId": batch_id,
    "cardKeys": card_keys[:50],
    "workTypes": sorted(removed_types),
    "matched": matched,
    "updated": updated,
  })
  return {
    "portalId": str(numeric_portal_id),
    "deleted": updated,
    "matched": matched,
    "workTypes": sorted(removed_types),
    "workflow": approval_workflow(numeric_portal_id, user),
    "workPeriods": updated_work_periods,
  }


def reorder_card_work_tasks(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  batch_id = str(payload.get("batchId") or payload.get("batch_id") or "").strip()[:120]
  raw_card_keys = payload.get("cardKeys") if isinstance(payload.get("cardKeys"), list) else []
  card_keys = []
  seen_card_keys = set()
  for raw_key in raw_card_keys:
    card_key = draft_card_key(raw_key)
    if card_key and card_key not in seen_card_keys:
      seen_card_keys.add(card_key)
      card_keys.append(card_key)
  if not batch_id or len(card_keys) < 2:
    raise ValueError("invalid_task_order")

  init_db()
  updated = 0
  with connect_db() as db:
    rows = db.execute(
      """
      SELECT id, card_key, payload_json, created_at, updated_at
      FROM card_drafts
      WHERE portal_id = ?
        AND json_extract(payload_json, '$.meta.batch.id') = ?
      """,
      (numeric_portal_id, batch_id),
    ).fetchall()
    if not rows:
      raise ValueError("task_batch_not_found")

    rows_by_key = {row["card_key"]: row for row in rows}
    ordered_keys = [card_key for card_key in card_keys if card_key in rows_by_key]
    if len(ordered_keys) < 2:
      raise ValueError("invalid_task_order")

    def row_position(row):
      try:
        draft_payload = json.loads(row["payload_json"])
      except (TypeError, json.JSONDecodeError):
        return len(rows)
      meta = draft_payload.get("meta") if isinstance(draft_payload.get("meta"), dict) else {}
      batch = meta.get("batch") if isinstance(meta.get("batch"), dict) else {}
      try:
        return int(batch.get("position"))
      except (TypeError, ValueError):
        return len(rows)

    tail_rows = [
      row
      for row in rows
      if row["card_key"] not in set(ordered_keys)
    ]
    tail_rows.sort(key=lambda row: (row_position(row), row["created_at"] or "", row["card_key"]))
    next_keys = [*ordered_keys, *[row["card_key"] for row in tail_rows]]
    positions = {card_key: index for index, card_key in enumerate(next_keys)}

    for row in rows:
      try:
        draft_payload = json.loads(row["payload_json"])
      except (TypeError, json.JSONDecodeError):
        continue
      draft_payload = normalize_card_draft_payload(draft_payload)
      meta = draft_payload.get("meta") if isinstance(draft_payload.get("meta"), dict) else {}
      batch = meta.get("batch") if isinstance(meta.get("batch"), dict) else {}
      if str(batch.get("id") or "") != batch_id:
        continue
      next_position = positions.get(row["card_key"])
      if next_position is None:
        continue
      previous_position = batch.get("position")
      try:
        previous_position = int(previous_position)
      except (TypeError, ValueError):
        previous_position = None
      if previous_position == next_position:
        continue
      batch["position"] = next_position
      meta["batch"] = batch
      draft_payload["meta"] = meta
      db.execute(
        """
        UPDATE card_drafts
        SET payload_json = ?, audit_status = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND portal_id = ?
        """,
        (
          json.dumps(draft_payload, ensure_ascii=False, separators=(",", ":")),
          draft_payload.get("auditStatus") or "idle",
          user_login_value(user) or None,
          row["id"],
          numeric_portal_id,
        ),
      )
      updated += 1

  record_admin_event(user, "card_work_tasks_reordered", "portal", numeric_portal_id, portal_id=numeric_portal_id, details={
    "batchId": batch_id,
    "cardKeys": card_keys[:200],
    "updated": updated,
  })
  return {
    "portalId": str(numeric_portal_id),
    "batchId": batch_id,
    "updated": updated,
    "workflow": approval_workflow(numeric_portal_id, user),
  }


CARD_WORK_EVENT_ACTIONS = {
  "opened": "открыта в конвейере",
  "skipped": "пропущена в текущем проходе",
  "deferred": "перенесена на позже",
  "quick_completed": "закрыта быстрым действием",
  "audit_completed": "аудит карточки готов",
  "audit_failed": "аудит карточки не выполнен",
  "semantic_final_imported": "итоговое СЯ загружено из файла",
  "content_reoptimized": "контент переоптимизирован по итоговому СЯ",
  "content_reoptimize_failed": "переоптимизация по итоговому СЯ не выполнена",
}


def log_card_work_event(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  card_key = draft_card_key(payload.get("cardKey") or payload.get("card_key"))
  action = str(payload.get("action") or "").strip()[:40]
  if not card_key or action not in CARD_WORK_EVENT_ACTIONS:
    raise ValueError("invalid_task_event")
  work_type = str(payload.get("workType") or payload.get("work_type") or "").strip()
  work_type_label = WORK_TYPE_LABELS.get(work_type, work_type)
  batch_id = str(payload.get("batchId") or payload.get("batch_id") or "").strip()[:120]
  comment = str(payload.get("reason") or "").strip()[:400]

  init_db()
  with connect_db() as db:
    row = db.execute(
      """
      SELECT card_key, nm_id, vendor_code
      FROM card_drafts
      WHERE portal_id = ? AND card_key = ?
      """,
      (numeric_portal_id, card_key),
    ).fetchone()
    if not row:
      raise ValueError("task_not_found")
    reason_parts = [CARD_WORK_EVENT_ACTIONS[action]]
    if work_type_label:
      reason_parts.append(work_type_label)
    if batch_id:
      reason_parts.append(f"batch {batch_id}")
    if comment:
      reason_parts.append(comment)
    event = {
      "status": action,
      "action": action,
      "actorLogin": user_login_value(user) or "",
      "assigneeLogin": "",
      "reason": " · ".join(reason_parts)[:1000],
      "eventAt": utc_now().isoformat(),
      "nmID": str(row["nm_id"] or payload.get("nmID") or payload.get("nm_id") or "")[:80],
      "vendorCode": str(row["vendor_code"] or payload.get("vendorCode") or payload.get("vendor_code") or "")[:120],
    }
    insert_card_approval_event(db, numeric_portal_id, card_key, event)

  return {
    "portalId": str(numeric_portal_id),
    "cardKey": card_key,
    "action": action,
    "workflow": approval_workflow(numeric_portal_id, user),
  }


def complete_card_work_task(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  card_key = draft_card_key(payload.get("cardKey") or payload.get("card_key"))
  work_types = normalize_optional_work_types([payload.get("workType") or payload.get("work_type")])
  if not card_key or not work_types:
    raise ValueError("invalid_task_complete")
  work_type = work_types[0]
  batch_id = str(payload.get("batchId") or payload.get("batch_id") or "").strip()[:120]
  comment = str(payload.get("reason") or "").strip()[:400]
  now = utc_now().isoformat()
  actor = user_login_value(user) or ""
  updated = False
  already_done = False
  updated_work_periods = []

  init_db()
  with connect_db() as db:
    row = db.execute(
      """
      SELECT id, card_key, nm_id, vendor_code, payload_json, updated_at, updated_by, created_by
      FROM card_drafts
      WHERE portal_id = ? AND card_key = ?
      """,
      (numeric_portal_id, card_key),
    ).fetchone()
    if not row:
      raise ValueError("task_not_found")
    try:
      previous_payload = normalize_card_draft_payload(json.loads(row["payload_json"]))
    except (TypeError, json.JSONDecodeError):
      previous_payload = normalize_card_draft_payload({})
    next_payload = normalize_card_draft_payload(previous_payload)
    meta = next_payload.get("meta") if isinstance(next_payload.get("meta"), dict) else {}
    batch = meta.get("batch") if isinstance(meta.get("batch"), dict) else {}
    current_work_types = normalize_optional_work_types(batch.get("workTypes"))
    if work_type not in current_work_types and not task_work_type_done(meta, work_type):
      raise ValueError("task_work_type_not_found")
    already_done = task_work_type_done(meta, work_type)
    if not already_done:
      completions = meta.get("manualTaskCompletions") if isinstance(meta.get("manualTaskCompletions"), dict) else {}
      completions[work_type] = {
        "status": "done",
        "completedAt": now,
        "completedBy": actor,
        "reason": comment,
        "batchId": batch.get("id") or batch_id,
      }
      meta["manualTaskCompletions"] = completions
      next_payload["meta"] = meta
      db.execute(
        """
        UPDATE card_drafts
        SET payload_json = ?, audit_status = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND portal_id = ?
        """,
        (
          json.dumps(next_payload, ensure_ascii=False, separators=(",", ":")),
          next_payload.get("auditStatus") or "idle",
          actor or None,
          row["id"],
          numeric_portal_id,
        ),
      )
      updated = True
      updated_work_periods = sync_work_period_task_statuses_for_draft_in_db(
        db,
        numeric_portal_id,
        next_payload,
        previous_payload,
        user,
      )

    reason_parts = [CARD_WORK_EVENT_ACTIONS["quick_completed"], WORK_TYPE_LABELS.get(work_type, work_type)]
    if batch.get("id") or batch_id:
      reason_parts.append(f"batch {batch.get('id') or batch_id}")
    if already_done:
      reason_parts.append("уже была закрыта")
    if comment:
      reason_parts.append(comment)
    insert_card_approval_event(db, numeric_portal_id, card_key, {
      "status": "quick_completed",
      "action": "quick_completed",
      "actorLogin": actor,
      "assigneeLogin": "",
      "reason": " · ".join(reason_parts)[:1000],
      "eventAt": now,
      "nmID": str(row["nm_id"] or payload.get("nmID") or payload.get("nm_id") or "")[:80],
      "vendorCode": str(row["vendor_code"] or payload.get("vendorCode") or payload.get("vendor_code") or "")[:120],
    })

  record_admin_event(user, "card_work_task_completed", "portal", numeric_portal_id, portal_id=numeric_portal_id, details={
    "cardKey": card_key,
    "workType": work_type,
    "batchId": batch_id,
    "updated": updated,
    "alreadyDone": already_done,
  })
  return {
    "portalId": str(numeric_portal_id),
    "cardKey": card_key,
    "workType": work_type,
    "completed": True,
    "updated": updated,
    "alreadyDone": already_done,
    "workflow": approval_workflow(numeric_portal_id, user),
    "workPeriods": updated_work_periods,
  }


def audit_draft_payload_from_result(audit_payload, previous_payload):
  previous_payload = normalize_card_draft_payload(previous_payload)
  draft_content = audit_payload.get("draftContent") if isinstance(audit_payload.get("draftContent"), dict) else {}
  title = draft_content.get("title") if isinstance(draft_content.get("title"), dict) else {}
  description = draft_content.get("description") if isinstance(draft_content.get("description"), dict) else {}
  characteristics = draft_content.get("characteristics") if isinstance(draft_content.get("characteristics"), dict) else {}
  previous_meta = previous_payload.get("meta") if isinstance(previous_payload.get("meta"), dict) else {}
  previous_history = previous_meta.get("auditHistory") if isinstance(previous_meta.get("auditHistory"), list) else []
  audit_entry = audit_payload.get("auditEntry") if isinstance(audit_payload.get("auditEntry"), dict) else {}
  next_history = [audit_entry, *previous_history] if audit_entry else previous_history
  meta = {
    **previous_meta,
    "auditHistory": next_history[:20],
    "auditResult": audit_payload.get("auditResult") if isinstance(audit_payload.get("auditResult"), dict) else {},
    "evidenceSummary": audit_payload.get("evidenceSummary") if isinstance(audit_payload.get("evidenceSummary"), dict) else {},
  }
  return normalize_card_draft_payload({
    "version": 2,
    "auditStatus": "done",
    "content": {
      "title": {
        "value": title.get("value") or "",
        "source": title.get("source") or "audit",
        "reason": title.get("reason") or "",
      },
      "description": {
        "value": description.get("value") or "",
        "source": description.get("source") or "audit",
        "reason": description.get("reason") or "",
      },
      "characteristics": characteristics,
    },
    "prices": previous_payload.get("prices") if isinstance(previous_payload.get("prices"), dict) else {},
    "stocks": previous_payload.get("stocks") if isinstance(previous_payload.get("stocks"), dict) else {},
    "meta": meta,
  })


def public_audit_task_error_reason(exc):
  if isinstance(exc, (AttributeError, TypeError, KeyError, IndexError)):
    return "invalid_audit_result"
  if isinstance(exc, TimeoutError):
    return "timeout"
  if isinstance(exc, RuntimeError):
    return "service_secret_unavailable"
  return "internal_error"


def audit_and_save_card_task(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  card_key = draft_card_key(payload.get("cardKey") or payload.get("card_key"))
  if not card_key:
    raise ValueError("invalid_card_key")

  init_db()
  with connect_db() as db:
    portal = db.execute(
      "SELECT cards_snapshot_json FROM portals WHERE id = ?",
      (numeric_portal_id,),
    ).fetchone()
    if not portal:
      raise ValueError("portal_not_found")
    draft_row = db.execute(
      """
      SELECT payload_json, nm_id, vendor_code
      FROM card_drafts
      WHERE portal_id = ? AND card_key = ?
      """,
      (numeric_portal_id, card_key),
    ).fetchone()
    if not draft_row:
      raise ValueError("task_not_found")
    try:
      previous_payload = json.loads(draft_row["payload_json"])
    except (TypeError, json.JSONDecodeError):
      previous_payload = normalize_card_draft_payload({})
    snapshot_card = snapshot_card_lookup(portal["cards_snapshot_json"]).get(card_key) or {}

  raw_card = payload.get("card") if isinstance(payload.get("card"), dict) else {}
  card = snapshot_card or raw_card
  if not card:
    raise ValueError("card_not_found")
  work_type = str(payload.get("workType") or payload.get("work_type") or "").strip()
  batch_id = str(payload.get("batchId") or payload.get("batch_id") or "").strip()[:120]
  context_token = mpstats_call_context_start(user, "Пачка: аудит карточки", portal_id=numeric_portal_id, card_key=card_key, nm_id=card.get("nmID") or card.get("nmId"), details={
    "batchId": batch_id,
    "workType": work_type,
  })
  try:
    audit_payload = build_card_audit(
      numeric_portal_id,
      card_key,
      card,
      subject_characteristics=None,
      mpstats_characteristics=None,
      period=payload.get("period"),
      audit_competitors=payload.get("auditCompetitors") or payload.get("competitorsForAudit"),
    )
  finally:
    mpstats_call_context_stop(context_token)

  next_payload = audit_draft_payload_from_result(audit_payload, previous_payload)
  nm_id = card.get("nmID") or card.get("nmId") or card.get("nm_id") or draft_row["nm_id"] or payload.get("nmID") or ""
  vendor_code = card.get("vendorCode") or card.get("vendor_code") or draft_row["vendor_code"] or payload.get("vendorCode") or ""
  draft = save_card_draft(numeric_portal_id, card_key, nm_id, vendor_code, next_payload, user)
  log_card_work_event(numeric_portal_id, {
    "cardKey": card_key,
    "action": "audit_completed",
    "workType": work_type,
    "batchId": batch_id,
  }, user)
  return {
    "portalId": str(numeric_portal_id),
    "cardKey": card_key,
    "draft": draft,
    "auditEntry": audit_payload.get("auditEntry"),
    "evidenceSummary": audit_payload.get("evidenceSummary"),
    "workflow": approval_workflow(numeric_portal_id, user),
  }


def delete_completed_approval_task(portal_id, payload, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  payload = payload if isinstance(payload, dict) else {}
  card_key = draft_card_key(payload.get("cardKey") or payload.get("card_key"))
  work_type = str(payload.get("workType") or payload.get("work_type") or "").strip()
  if not card_key or work_type != "semantic":
    raise ValueError("invalid_completed_task_delete")

  init_db()
  removed = 0
  now = utc_now().isoformat()
  with connect_db() as db:
    row = db.execute(
      """
      SELECT id, card_key, payload_json
      FROM card_drafts
      WHERE portal_id = ? AND card_key = ?
      """,
      (numeric_portal_id, card_key),
    ).fetchone()
    if not row:
      raise ValueError("completed_task_not_found")
    try:
      draft_payload = json.loads(row["payload_json"])
    except (TypeError, json.JSONDecodeError):
      draft_payload = normalize_card_draft_payload({})
    draft_payload = normalize_card_draft_payload(draft_payload)
    meta = draft_payload.get("meta") if isinstance(draft_payload.get("meta"), dict) else {}
    batch = meta.get("batch") if isinstance(meta.get("batch"), dict) else {}
    if batch:
      raise ValueError("completed_task_has_batch")
    final_export = meta.get("semanticCoreFinal") if isinstance(meta.get("semanticCoreFinal"), dict) else {}
    if not semantic_core_final_exists(meta):
      raise ValueError("completed_task_not_found")

    removal_history = meta.get("completedTaskRemovalHistory") if isinstance(meta.get("completedTaskRemovalHistory"), list) else []
    removal_history.append({
      "at": now,
      "by": user_login_value(user),
      "cardKey": row["card_key"],
      "workType": work_type,
      "completedAt": final_export.get("updatedAt") or final_export.get("createdAt") or "",
      "completedBy": final_export.get("updatedBy") or final_export.get("createdBy") or "",
      "reason": str(payload.get("reason") or "removed_from_completed_tasks")[:400],
    })
    meta["completedTaskRemovalHistory"] = removal_history[-50:]
    meta.pop("semanticCoreFinal", None)
    draft_payload["meta"] = meta
    db.execute(
      """
      UPDATE card_drafts
      SET payload_json = ?, audit_status = ?, updated_by = ?, updated_at = CURRENT_TIMESTAMP
      WHERE id = ? AND portal_id = ?
      """,
      (
        json.dumps(draft_payload, ensure_ascii=False, separators=(",", ":")),
        draft_payload.get("auditStatus") or "idle",
        user_login_value(user) or None,
        row["id"],
        numeric_portal_id,
      ),
    )
    removed = 1

  record_admin_event(user, "completed_task_deleted", "portal", numeric_portal_id, portal_id=numeric_portal_id, details={
    "cardKey": card_key,
    "workType": work_type,
    "removed": removed,
  })
  return {
    "portalId": str(numeric_portal_id),
    "deleted": removed,
    "cardKey": card_key,
    "workType": work_type,
    "workflow": approval_workflow(numeric_portal_id, user),
  }


def event_minutes_between(start, end):
  if not start or not end:
    return None
  try:
    start_dt = dt.datetime.fromisoformat(str(start).replace("Z", "+00:00"))
    end_dt = dt.datetime.fromisoformat(str(end).replace("Z", "+00:00"))
  except ValueError:
    return None
  return max(0, int((end_dt - start_dt).total_seconds() // 60))


def event_sort_timestamp(value):
  text = str(value or "").strip()
  if not text:
    return 0
  if " " in text and "T" not in text:
    text = text.replace(" ", "T", 1)
  try:
    parsed = dt.datetime.fromisoformat(text.replace("Z", "+00:00"))
  except ValueError:
    return 0
  if parsed.tzinfo is None:
    parsed = parsed.replace(tzinfo=dt.timezone.utc)
  return parsed.timestamp()


def approval_workflow(portal_id, user):
  try:
    numeric_portal_id = int(portal_id)
  except (TypeError, ValueError) as exc:
    raise ValueError("invalid_portal_id") from exc
  if not user_can_access_portal(user, numeric_portal_id):
    raise PermissionError("forbidden")
  init_db()
  with connect_db() as db:
    portal = db.execute(
      "SELECT cards_snapshot_json FROM portals WHERE id = ?",
      (numeric_portal_id,),
    ).fetchone()
    if not portal:
      raise ValueError("portal_not_found")
    snapshot_lookup = snapshot_card_lookup(portal["cards_snapshot_json"])
    task_rows = db.execute(
      """
      SELECT *
      FROM card_drafts
      WHERE portal_id = ?
        AND COALESCE(NULLIF(json_extract(payload_json, '$.meta.approval.status'), ''), 'draft') IN ('draft', 'submitted', 'changes_requested', 'approved', 'exported')
      ORDER BY
        CASE COALESCE(NULLIF(json_extract(payload_json, '$.meta.approval.status'), ''), 'draft')
          WHEN 'submitted' THEN 1
          WHEN 'changes_requested' THEN 2
          WHEN 'draft' THEN 3
          ELSE 4
        END,
        updated_at DESC
      """,
      (numeric_portal_id,),
    ).fetchall()
    all_event_rows = db.execute(
      """
      SELECT *
      FROM card_approval_events
      WHERE portal_id = ?
      ORDER BY event_at DESC, id DESC
      """,
      (numeric_portal_id,),
    ).fetchall()
    event_rows = all_event_rows[:50]

  tasks = [
    task
    for task in (public_approval_task(row, snapshot_lookup) for row in task_rows)
    if task.get("workTypes")
  ]
  completed_tasks = [
    task
    for row in task_rows
    for task in public_completed_approval_tasks(row, snapshot_lookup)
  ]
  completed_tasks.sort(key=lambda task: event_sort_timestamp(task.get("completedAt") or task.get("updatedAt")), reverse=True)
  completed_count = len(completed_tasks)
  completed_tasks = completed_tasks[:200]
  draft_tasks = [task for task in tasks if task["status"] == "draft"]
  submitted_tasks = [task for task in tasks if task["status"] == "submitted"]
  returned_tasks = [task for task in tasks if task["status"] == "changes_requested"]
  approved_tasks = [task for task in tasks if task["status"] == "approved"]
  latest_submitted_by_card = {}
  approval_minutes = []
  for row in reversed(all_event_rows):
    if row["status"] == "submitted":
      latest_submitted_by_card[row["card_key"]] = row["event_at"]
    elif row["status"] == "approved":
      minutes = event_minutes_between(latest_submitted_by_card.get(row["card_key"]), row["event_at"])
      if minutes is not None:
        approval_minutes.append(minutes)
  approval_minutes = [value for value in approval_minutes if value is not None]
  pending_minutes = [
    event_minutes_between(task.get("submittedAt"), dt.datetime.now(dt.timezone.utc).isoformat())
    for task in submitted_tasks
  ]
  pending_minutes = [value for value in pending_minutes if value is not None]
  recent_events = []
  for row in event_rows:
    card = snapshot_lookup.get(row["card_key"], {})
    recent_events.append({
      "id": row["id"],
      "cardKey": row["card_key"],
      "nmID": row["nm_id"] or card.get("nmID") or "",
      "vendorCode": row["vendor_code"] or card.get("vendorCode") or "",
      "title": card.get("title") or row["vendor_code"] or row["nm_id"] or "Карточка WB",
      "subjectName": card.get("subjectName") or "",
      "status": row["status"],
      "action": row["action"],
      "actorLogin": row["actor_login"],
      "assigneeLogin": row["assignee_login"],
      "reason": row["reason"],
      "eventAt": row["event_at"],
    })
  return {
    "tasks": tasks,
    "analytics": {
      "pendingCount": len(submitted_tasks),
      "draftCount": len(draft_tasks),
      "returnedCount": len(returned_tasks),
      "approvedCount": len(approved_tasks),
      "completedCount": completed_count,
      "eventCount": len(all_event_rows),
      "avgApprovalMinutes": round(sum(approval_minutes) / len(approval_minutes)) if approval_minutes else None,
      "avgPendingMinutes": round(sum(pending_minutes) / len(pending_minutes)) if pending_minutes else None,
      "lastEventAt": recent_events[0]["eventAt"] if recent_events else "",
    },
    "completedTasks": completed_tasks,
    "recentEvents": recent_events,
  }


